sn_aia_agent.context_processing_script:
(function(task, user_utterance, agent_id, context) {
    var pc = (context && context.pageContext) ? context.pageContext : {};
    // Build Agent needs an explicit target application scope.
    pc.scope = pc.scope || 'x_snc_forecast_v_0';
    pc.scopeId = pc.scopeId || 'a4fd2da13bf8be5062f31831a3e45ac9';
    pc.app_sys_id = pc.app_sys_id || 'a4fd2da13bf8be5062f31831a3e45ac9';
    pc.table = pc.table || 'sys_app';
    pc.record_sys_id = pc.record_sys_id || 'a4fd2da13bf8be5062f31831a3e45ac9';
    pc.experience = pc.experience || 'WDF Lab';
    return { pageContext: pc, triggerContext: (context ? context.triggerContext : null) };
})(task, user_utterance, agent_id, context);
